INSERT INTO `teams` (`id`, `name`, `code`, `description`, `team_lead_id`, `created_by`, `updated_by`, `deleted_at`, `created_at`, `updated_at`) VALUES
(1, 'QA', 'QA-8630', 'Ensures the quality, reliability, and performance of projects through comprehensive testing and continuous quality improvement.', 90, NULL, NULL, NULL, '2026-07-07 19:22:13', '2026-07-10 20:41:27'),
(2, 'HTML', 'HTML-3035', 'Builds responsive, accessible, and visually accurate user interfaces that deliver seamless experiences across devices.', 22, NULL, NULL, NULL, '2026-07-09 12:17:22', '2026-07-09 12:17:22'),
(3, 'PHP', 'PHP-3558', 'Develops secure, scalable, and high-performing web applications and backend solutions using PHP technologies.', 21, NULL, NULL, NULL, '2026-07-09 12:17:50', '2026-07-09 12:17:50'),
(4, 'WordPress', 'WORD-5112', 'Creates, customizes, and maintains responsive, secure, and high-performing WordPress websites and solutions.', 49, NULL, NULL, NULL, '2026-07-09 12:19:14', '2026-07-13 09:39:11'),
(5, 'React', 'REAC-4432', 'Develops modern, interactive, and scalable web applications with fast, seamless user experiences.', NULL, NULL, NULL, NULL, '2026-07-09 12:19:43', '2026-07-13 10:18:25'),
(6, 'Digital Marketing', 'DIGI-0917', 'Drives brand visibility, audience engagement, and business growth through creative, data-driven digital marketing strategies.', 26, NULL, NULL, NULL, '2026-07-09 12:20:09', '2026-07-13 10:27:56'),
(7, 'Project Coordinators', 'PROJ-1362', 'Responsible for planning, coordinating, and monitoring project activities, ensuring smooth communication between clients and internal teams while keeping projects on schedule and within scope.', 28, NULL, NULL, NULL, '2026-07-13 09:45:36', '2026-07-13 09:45:36'),
(8, 'Project Management', 'PROJ-1589', 'Responsible for planning, executing, and overseeing projects from initiation to completion, ensuring they are delivered on time, within scope, and within budget.', 87, NULL, NULL, NULL, '2026-07-13 09:46:34', '2026-07-13 09:46:34'),
(9, 'Accounts', 'ACCO-3819', 'Manage the organization\'s financial records, transactions, payroll, invoicing, budgeting, and compliance to ensure accurate and timely financial operations.', 23, NULL, NULL, NULL, '2026-07-13 10:49:44', '2026-07-13 10:49:44');
